alter table public.reminders\n  add column if not exists notify_telegram boolean not null default false,\n  add column if not exists telegram_sent_at timestamptz null,\n  add column if not exists telegram_locked_at timestamptz null,\n  add column if not exists telegram_attempts integer not null default 0,\n  add column if not exists telegram_last_error text null;\n\ncreate index if not exists reminders_telegram_due_idx\n  on public.reminders (notify_telegram, completed, due_at)\n  where notify_telegram = true and completed = false;\n\ncreate table if not exists public.telegram_connection (\n  user_id uuid primary key references auth.users(id) on delete cascade,\n  chat_id text not null,\n  username text null,\n  first_name text null,\n  connected_at timestamptz not null default now()\n);\n\ncreate unique index if not exists telegram_connection_chat_id_idx\n  on public.telegram_connection (chat_id);\n\ncreate table if not exists public.telegram_link_token (\n  user_id uuid primary key references auth.users(id) on delete cascade,\n  token_hash text not null unique,\n  expires_at timestamptz not null,\n  used_at timestamptz null\n);\n\nalter table public.telegram_connection enable row level security;\nalter table public.telegram_link_token enable row level security;\n\ndrop policy if exists telegram_connection_primary_owner on public.telegram_connection;\ndrop policy if exists telegram_link_token_primary_owner on public.telegram_link_token;\n\ncreate policy telegram_connection_primary_owner\n  on public.telegram_connection for all to authenticated\n  using ((select auth.uid()) = user_id)\n  with check ((select auth.uid()) = user_id);\n\ncreate policy telegram_link_token_primary_owner\n  on public.telegram_link_token for all to authenticated\n  using ((select auth.uid()) = user_id)\n  with check ((select auth.uid()) = user_id);\n\ndrop trigger if exists telegram_connection_prevent_bulk_delete on public.telegram_connection;\ncreate trigger telegram_connection_prevent_bulk_delete\nbefore delete on public.telegram_connection\nfor each statement execute function public.prevent_bulk_delete();\n\ndrop trigger if exists telegram_link_token_prevent_bulk_delete on public.telegram_link_token;\ncreate trigger telegram_link_token_prevent_bulk_delete\nbefore delete on public.telegram_link_token\nfor each statement execute function public.prevent_bulk_delete();\n\nselect vault.create_secret(encode(gen_random_bytes(32), 'hex'), 'onevault_telegram_webhook_secret')\nwhere not exists (select 1 from vault.decrypted_secrets where name = 'onevault_telegram_webhook_secret');\n\nselect vault.create_secret(encode(gen_random_bytes(32), 'hex'), 'onevault_telegram_cron_secret')\nwhere not exists (select 1 from vault.decrypted_secrets where name = 'onevault_telegram_cron_secret');\n\nselect cron.schedule(\n  'onevault-telegram-worker',\n  '* * * * *',\n  '$cron$\n    select net.http_post(\n      url := 'https://gskxfpuotdynbeokruhj.supabase.co/functions/v1/telegram?action=worker',\n      headers := jsonb_build_object(\n        'Content-Type', 'application/json',\n        'x-onevault-cron-secret',\n        (select decrypted_secret from vault.decrypted_secrets where name = 'onevault_telegram_cron_secret')\n      ),\n      body := '{}'::jsonb\n    ) as request_id;\n  $cron$\n)\nwhere not exists (select 1 from cron.job where jobname = 'onevault-telegram-worker');\n